# 载入程序词汇
app = json.load(open(r'D:\できる日本語 单词卡\app_words.json', encoding='utf-8'))

def norm(s):
    if s is None: return ''
    s = s.replace('~','～').replace(' ','').replace('　','')
    # 去掉句尾句号
    s = s.rstrip('。．.')
    # 去掉括号标注（（お）（な）（さん）（へ）等）
    s = re.sub(r'[（(][^）)]*[）)]', '', s)
    return s

print('===== 程序词汇 vs 官方PDF词汇表 校验报告 =====\n')
for k in sorted(pdf_words, key=int):
    pdfset = set(norm(w) for w in pdf_words[k])
    appset = set(norm(w['kanji']) for w in app[str(k)])
    missing = pdfset - appset
    extra = appset - pdfset
    print('【第{}課】PDF词条数={} | 程序词条数={}'.format(k, len(pdfset), len(appset)))
    if missing:
        print('  ▲ 程序缺失 ({}个):'.format(len(missing)))
        for w in sorted(missing):
            print('    - ' + w)
    if extra:
        print('  ▽ 程序独有 ({}个):'.format(len(extra)))
        for w in sorted(extra):
            print('    + ' + w)
    print()

# 汇总统计
print('===== 汇总 =====')
total_pdf = sum(len(set(norm(w) for w in v)) for v in pdf_words.values())
total_app = sum(len(set(norm(w['kanji']) for w in app[str(k)])) for k in sorted(pdf_words, key=int))
print('PDF官方词汇总词条数(含句子/寒暄):', total_pdf)
print('程序总词条数:', total_app)
